#!/usr/bin/env bash
# Render explicit values from catalogue JSON on stdin; never import inherited defaults.
set -euo pipefail
jq -er '
  if (.repositories | type) != "object" or (.repositories | length) < 10 or
    any(.repositories[]; (.type | type) != "string" or
      (.auto_merge | type) != "boolean" or (.scan_actions | type) != "boolean" or .copilot_review != false)
  then error("complete explicit repository values are required") else . end |
  "# Generated by scripts/custom-properties from custom-properties/catalogue.json.\n# Do not edit: go -C scripts/custom-properties run . --root ../.. --render",
  (.repositories | to_entries | sort_by(.key)[] | . as $repo |
    [{name:"Type",kind:"single_select",value:.value.type},
     {name:"EnableAutoMerge",kind:"true_false",value:(.value.auto_merge|tostring)},
     {name:"ScanGitHubActions",kind:"true_false",value:(.value.scan_actions|tostring)},
     {name:"AutomaticallyRequestCopilotCodeReview",kind:"true_false",value:(.value.copilot_review|tostring)}][] |
    "---\napiVersion: repo.github.m.upbound.io/v1alpha1\nkind: RepositoryCustomProperty\nmetadata:\n  name: \(if $repo.key == ".github" then "dot-github" else $repo.key end)-\(.name|ascii_downcase)\nspec:\n  managementPolicies: [Observe, Create, Update]\n  forProvider:\n    repository: \($repo.key|tojson)\n    propertyName: \(.name)\n    propertyType: \(.kind)\n    propertyValue: [\(.value|tojson)]\n  providerConfigRef:\n    kind: ProviderConfig\n    name: default")
'
